package net.battlespades.bot;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotMessages.*;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.BotVectors.*;
import static net.battlespades.bot.BotUnofficialPolicy.*;

/** Community mode actions from sanctioned objective facts and local terrain/LOS. */
final class BrainUnofficial {
    private static final org.tomlj.TomlParseResult C=net.battlespades.catalog.SourceCatalog.load("bot-community");
    private static final Set<String> SOLO=Set.of("floor_tax","hot_potato","one_in_the_spade","borrowed_arsenal");
    private final BotNavigationWorld world;private final BrainIntents intents;private final RecoveryDriver skills;private final BrainSkills skillIntents;private final BrainNavigation navigation;private final BrainCombat combat;
    BrainUnofficial(BotNavigationWorld world,BrainIntents intents,RecoveryDriver skills,BrainSkills skillIntents,BrainNavigation navigation,BrainCombat combat){this.world=world;this.intents=intents;this.skills=skills;this.skillIntents=skillIntents;this.navigation=navigation;this.combat=combat;}
    static Player policy(Player p,boolean alive,int blocks,int clip,int reserve,int team,boolean dig){return copy(p,alive,blocks,clip,reserve,team,dig);}
    static Perception combatView(Perception f,Player observer){var statuses=new HashMap<Integer,Map<String,Object>>();for(var o:list(f.fun(),"players")){var row=map(o);statuses.put(integer(row,"player_id",-1),row);}var players=new ArrayList<Player>();boolean digging=Boolean.TRUE.equals(C.getBoolean(f.mode()+".digging"))&&f.modePhase().equals("live"),building=Boolean.TRUE.equals(C.getBoolean(f.mode()+".building"));for(var p:f.players()){var info=statuses.get(p.id());boolean visible=info!=null&&flag(info,"active")&&!flag(info,"prisoner");if(info!=null&&flag(info,"disguised")&&p.team()!=observer.team())visible&=distance(observer.position(),p.position())<3||f.createdAt()<number(f.fun(),"clue_until",0)&&distance(observer.position(),p.position())<10;boolean armed=p.loadout().stream().anyMatch(BrainInventory.FIREARMS::contains);players.add(policy(p,p.alive()&&visible,building?p.blocks():0,armed?p.ammoClip():0,armed?p.ammoReserve():0,SOLO.contains(f.mode())?1000+p.id():p.team(),digging));}return new Perception(f.frameId(),f.mapEpoch(),f.modeEpoch(),f.topologyVersion(),f.observerId(),f.observerGeneration(),f.createdAt(),f.mode(),players,f.profile(),f.entities(),f.objectives(),List.of(),f.modePhase(),f.behaviorVersion(),f.friendlyMischief(),f.localSafetyComplete(),f.fun());}
    Intent decide(Perception f,Player source,BotBrainState s,double now){var decision=BotUnofficialPolicy.decide(f,source);boolean dig=Boolean.TRUE.equals(C.getBoolean(f.mode()+".digging"))&&f.modePhase().equals("live");if(f.mode().equals("block_hunt"))dig=source.team()!=integer(f.fun(),"attackers",-1)&&Set.of("prepare","live").contains(f.modePhase());var p=policy(source,source.alive(),Boolean.TRUE.equals(C.getBoolean(f.mode()+".building"))?source.blocks():0,source.ammoClip(),source.ammoReserve(),source.team(),dig);int tool=BrainInventory.weapon(p,null);
        if(decision.directive().equals("hold")){skills.forget(p.id(),p.generation());return emit(f,p,s,decision,null,null,null,null,null);}if(decision.directive().equals("race"))return race(f,p,s,decision);if(decision.directive().equals("floor"))return floor(f,p,s,decision);
        if(decision.directive().equals("hide")){var info=list(f.fun(),"players").stream().map(BotUnofficialPolicy::map).filter(v->integer(v,"player_id",-1)==p.id()).findFirst().orElseThrow();if(flag(info,"disguised"))return emit(f,p,s,decision,null,null,null,null,null);if(distance(p.position(),decision.position())<1.5){if(Math.hypot(p.velocity().x(),p.velocity().y())>.1)return emit(f,p,s,decision,null,null,null,null,null);return emit(f,p,s,decision,null,null,BrainCombat.action(ActionKind.DISGUISE,-1),64,null);}}
        if(f.mode().equals("bridge_chicken")){var r=skillIntents.result(f,p,s,skills.considerGap(p,f.profile(),now,decision.position(),48),now);if(r!=null)return r;}
        var view=combatView(f,p);var actor=view.players().stream().filter(q->q.id()==p.id()).findFirst().orElseThrow();var profile=f.profile()==null?BrainInventory.fallback(p.id()):f.profile();
        if(decision.directive().equals("tag")){var visible=view.players().stream().filter(q->q.id()!=actor.id()&&q.alive()&&world.lineOfSight(actor.eye(),q.eye())).toList();if(integer(f.fun(),"holder",-1)==actor.id()&&!visible.isEmpty()){var target=visible.stream().min(Comparator.comparingDouble(q->distance(actor.position(),q.position()))).orElseThrow();return emit(f,p,s,decision,movement(direction(actor.position(),target.position()),false,Affordance.WALK),new Look(target.eye(),true,-1,0,0,false),distance(actor.position(),target.position())<3?BrainCombat.action(ActionKind.MELEE,0):Action.none(),0,null);}var holder=visible.stream().filter(q->q.id()==integer(f.fun(),"holder",-1)).findFirst().orElse(null);double angle=actor.id()*2.4+(int)(now/5);var away=holder==null?new Vector(Math.cos(angle),Math.sin(angle),0):direction(holder.position(),actor.position());var center=at(f.fun(),"center");var target=new Vector(Math.clamp(actor.position().x()+away.x()*12,center.x()-50,center.x()+50),Math.clamp(actor.position().y()+away.y()*12,center.y()-30,center.y()+30),actor.position().z());decision=new BotModeDecision(target,decision.role(),decision.sprint(),decision.arrivalRadius(),"",decision.posture(),decision.objectivePriority(),decision.engagementRadius(),decision.watchPosition());}
        else if(f.modePhase().equals("live")&&!decision.directive().equals("hide")){var target=BrainTargeting.visible(world,view,actor,s,decision);if(target!=null)return combat.fight(view,actor,target,s,profile,now,decision);}
        if(skills.active(p)){var r=skillIntents.step(f,p,s,now);if(r!=null)return r;}double gap=distance(p.position(),decision.position());
        if(now>=s.funActionAt){if(decision.directive().equals("stash")&&gap<1.5){s.funActionAt=now+1;return emit(f,p,s,decision,null,null,action(ActionKind.MODE_COMMAND,null,"stash"),null,null);}if(decision.directive().equals("paint")){Cell best=null;double reach=Double.POSITIVE_INFINITY;for(var o:list(f.fun(),"paint")){var row=(List<?>)o;var point=vector(row.getFirst());var c=new Cell((int)point.x(),(int)point.y(),(int)point.z());double d=distance(p.position(),point);if(((Number)row.get(1)).intValue()!=p.team()&&distance(p.eye(),centre(c))<4&&d<reach){reach=d;best=c;}}if(best!=null){s.funActionAt=now+.2;return emit(f,p,s,decision,null,null,action(ActionKind.PAINT,point(best),""),5,null);}}
            if(Set.of("repair","fortify").contains(decision.directive())){var cells=decision.directive().equals("repair")?list(f.fun(),"repair_cells").stream().map(BotUnofficialPolicy::vector).toList():fortify(f,p);for(var cell:cells)if(!world.solid((int)cell.x(),(int)cell.y(),(int)cell.z())&&distance(p.eye(),cell)<4){s.funActionAt=now+.25;return emit(f,p,s,decision,null,null,action(ActionKind.BUILD,cell,""),5,null);}}
            if(decision.directive().equals("demolish")){int digTool=p.loadout().stream().filter(t->t==2||t==0).findFirst().orElse(2);var core=new Cell((int)decision.position().x(),(int)decision.position().y(),(int)decision.position().z());var aim=centre(core);if(distance(p.eye(),aim)<4){s.funActionAt=now+.25;return emit(f,p,s,decision,null,look(aim),BrainCombat.action(ActionKind.MELEE,digTool),digTool,null);}if(core.z()<p.position().z()-5){var supports=new ArrayList<Cell>();for(int dx:new int[]{-4,4})for(int dy:new int[]{-4,4}){var c=new Cell(core.x()+dx,core.y()+dy,(int)Math.floor(p.position().z()+1));if(world.solid(c.x(),c.y(),c.z()))supports.add(c);}var cell=supports.stream().min(Comparator.comparingDouble(c->distance(p.position(),point(c)))).orElse(null);if(cell!=null){aim=centre(cell);decision=SimpleBotBrain.position(decision,new Vector(cell.x()+1.8,cell.y()+1.8,p.position().z()),1);if(distance(p.eye(),aim)<4){s.funActionAt=now+.25;return emit(f,p,s,decision,null,look(aim),BrainCombat.action(ActionKind.MELEE,digTool),digTool,null);}}}}
            if(decision.role().equals("fun_deliver_ball")){var destination=decision.position();double distance=gap;var ahead=f.players().stream().filter(q->q.team()==p.team()&&q.alive()&&q.id()!=p.id()&&distance(p.position(),q.position())>3&&distance(p.position(),q.position())<7&&distance(q.position(),destination)+3<distance&&world.lineOfSight(p.eye(),q.eye())).min(Comparator.comparingDouble(q->distance(q.position(),destination))).orElse(null);if(ahead!=null){s.funActionAt=now+2;return emit(f,p,s,decision,null,null,action(ActionKind.MODE_COMMAND,ahead.position(),"pass"),null,null);}}
        }
        return navigation.navigate(f,p,s,BrainGoals.from(decision),now);
    }
    private Intent floor(Perception f,Player p,BotBrainState s,BotModeDecision decision){var active=new HashSet<Integer>();for(var o:list(f.fun(),"players")){var row=map(o);if(flag(row,"active"))active.add(integer(row,"player_id",-1));}var rival=f.players().stream().filter(q->q.id()!=p.id()&&q.alive()&&active.contains(q.id())&&Math.abs(q.position().z()-p.position().z())<3&&world.lineOfSight(p.eye(),q.eye())).min(Comparator.comparingDouble(q->distance(q.position(),p.position()))).orElse(null);Vector best=null;double score=Double.NEGATIVE_INFINITY;for(int i=0;i<8;i++){double angle=(i+p.id())*Math.PI/4;var delta=new Vector(Math.cos(angle),Math.sin(angle),0);int safe=0,z=(int)Math.rint(p.position().z()+2.25);for(int d=1;d<=3;d++)if(world.solid((int)Math.floor(p.position().x()+delta.x()*d),(int)Math.floor(p.position().y()+delta.y()*d),z))safe++;double value=safe*10+dot(delta,s.funDirection);if(rival!=null)value+=dot(delta,direction(p.position(),rival.position()))*4;if(best==null||value>score){score=value;best=delta;}}s.funDirection=best;var movement=movement(best,score<20&&p.grounded(),Affordance.WALK);if(rival!=null){var target=new Vector(rival.position().x(),rival.position().y(),Math.rint(rival.position().z()+2.25)+.1);double reach=distance(p.eye(),target);if(reach<5)return emit(f,p,s,decision,movement,look(target),BrainCombat.action(ActionKind.MELEE,2),2,null);if(reach>6&&reach<18&&f.createdAt()>=s.funActionAt){s.funActionAt=f.createdAt()+6;return emit(f,p,s,decision,movement,look(new Vector(target.x(),target.y(),target.z()-4)),BrainCombat.action(ActionKind.FIRE,11),11,null);}}return emit(f,p,s,decision,movement,null,null,2,null);}
    private Intent race(Perception f,Player p,BotBrainState s,BotModeDecision decision){var checkpoints=list(f.fun(),"checkpoints").stream().map(BotUnofficialPolicy::vector).toList();var route=list(f.fun(),"route").stream().map(BotUnofficialPolicy::vector).toList();if(route.isEmpty())route=checkpoints;if(route.isEmpty())return emit(f,p,s,decision,null,null,null,null,"fun_missing_course");var info=list(f.fun(),"players").stream().map(BotUnofficialPolicy::map).filter(v->integer(v,"player_id",-1)==p.id()).findFirst().orElseThrow();var checkpoint=checkpoints.get(Math.min(integer(info,"checkpoint",0),checkpoints.size()-1));int first=nearest(route,checkpoint),last=nearest(route,decision.position());if(distance(p.position(),checkpoint)<3.5)s.funWaypoint=Math.min(first+1,last);int index=Math.min(Math.max(first+1,Math.min(last,s.funWaypoint)),route.size()-1);boolean broad=route.size()>32;if(flat(p.position(),route.get(index))<(broad?2.5:1.4)&&(p.grounded()||broad))index=Math.min(index+1,last);s.funWaypoint=index;var target=route.get(index);var delta=direction(p.position(),target);double ahead=broad?2.2:1.7;boolean jump=p.grounded()&&!world.solid((int)Math.floor(p.position().x()+delta.x()*ahead),(int)Math.floor(p.position().y()+delta.y()*ahead),(int)Math.rint(target.z()+2.25));return emit(f,p,s,decision,movement(delta,jump,jump||!p.grounded()?Affordance.JUMP:Affordance.WALK),look(target),null,null,null);}
    private static int nearest(List<Vector> points,Vector target){int best=0;for(int i=1;i<points.size();i++)if(distance(points.get(i),target)<distance(points.get(best),target))best=i;return best;}
    private static List<Vector> fortify(Perception f,Player p){var home=home(list(f.fun(),"homes"),p.team(),null);int x=(int)Math.floor(home.x())+3,y=(int)Math.floor(home.y()),z=(int)Math.floor(home.z()+2.25)-1;return List.of(new Vector(x,y-1,z),new Vector(x,y,z),new Vector(x,y+1,z));}
    private Intent emit(Perception f,Player p,BotBrainState s,BotModeDecision decision,Movement movement,Look look,Action action,Integer tool,String role){return intents.emit(f,s,movement==null?Movement.still():movement,look,tool==null?BrainInventory.weapon(p,null):tool,action==null?Action.none():action,Priority.TRAVERSAL,false,false,decision.position(),List.of(),role==null?decision.role():role,false);}
    private static Vector direction(Vector a,Vector b){double length=Math.max(.001,flat(a,b));return new Vector((b.x()-a.x())/length,(b.y()-a.y())/length,0);}
    private static double dot(Vector a,Vector b){return a.x()*b.x()+a.y()*b.y()+a.z()*b.z();}
    private static Movement movement(Vector direction,boolean jump,Affordance affordance){return new Movement(direction,jump,false,false,false,affordance,true,null,null,null,1);}
    private static Look look(Vector at){return new Look(at,false,-1,0,0,false);}
    private static Action action(ActionKind kind,Vector at,String arg){return new Action(kind,-1,at,null,arg,-1,0,0,0,0);}
    private static Vector point(Cell c){return new Vector(c.x(),c.y(),c.z());}
    private static Vector centre(Cell c){return new Vector(c.x()+.5,c.y()+.5,c.z()+.5);}
    private static Player copy(Player p,boolean alive,int blocks,int clip,int reserve,int team,boolean dig){return new Player(p.id(),p.generation(),team,p.classId(),alive,p.spawned(),p.position(),p.eye(),p.orientation(),p.velocity(),p.health(),p.tool(),blocks,clip,reserve,p.bot(),p.weaponTool(),p.loadout(),p.prefabs(),p.orientedStock(),p.carriedEntityId(),p.jetpackId(),p.jetpackFuel(),p.grounded(),p.wade(),p.reloading(),p.lastActionKind(),p.lastActionAccepted(),p.lastActionPosition(),p.lastActionFrame(),p.lastActionAt(),p.lastDamageAt(),p.lastDamageSourceId(),p.lastDamageSourcePosition(),p.lifeId(),p.deployableStock(),p.lastActionRequestId(),p.lastActionReason(),p.lastTaskAccepted(),p.lastTaskAt(),p.canShoot(),p.weaponAmmo(),p.spawnProtected(),p.lastDamageKind(),dig);}
}
